class A { String name() { return "A"; } }
class B extends A { @Override String name() { return "B"; } }
class C extends A { @Override String name() { return "C"; } }
public class Main {
    static A make(boolean flag) {
        return flag ? new B() : new C();
    }
    public static void main(String[] args) {
        A a = make(false);
        System.out.print(a.name() + ":");
        if (a instanceof B b) {
            System.out.print(b.name());
        }
        B b2 = (B) a;
        System.out.print(b2.name());
    }
}

